// -O2
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

// Converts a column of prices to another currency: the work being timed.
void convert(const double* in, double* out, std::size_t n, double rate) {
    for (std::size_t i = 0; i < n; ++i) {
        out[i] = in[i] * rate;
    }
}

int main() {
    const std::size_t n = 10'000'000;
    std::vector<double> prices(n);
    for (std::size_t i = 0; i < n; ++i) {
        prices[i] = 100.0 + i % 40 * 0.25;
    }
    double* converted = new double[n];  // fresh memory: nothing has touched it yet

    double best_ms = 1e9;
    for (int run = 1; run <= 5; ++run) {
        auto start = std::chrono::steady_clock::now();
        convert(prices.data(), converted, n, 0.5);
        auto stop = std::chrono::steady_clock::now();
        double ms = std::chrono::duration<double, std::milli>(stop - start).count();
        best_ms = std::min(best_ms, ms);
        // std::cout << "run " << run << ": " << ms << " ms\n";  // changes every run
    }
    // std::cout << "best: " << best_ms << " ms\n";

    double checksum = 0;
    for (std::size_t i = 0; i < n; ++i) {
        checksum += converted[i];
    }
    std::cout << std::fixed << std::setprecision(2) << "checksum " << checksum << '\n';
    delete[] converted;
    return 0;
}

