// -O2
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

// Mid price of every quote: the work being timed.
void mids(const double* bid, const double* ask, double* out, std::size_t n) {
    for (std::size_t i = 0; i < n; ++i) {
        out[i] = (bid[i] + ask[i]) / 2;
    }
}

int main() {
    std::size_t n;
    int runs;
    std::cin >> n >> runs;
    std::vector<double> bid(n), ask(n);
    for (std::size_t i = 0; i < n; ++i) {
        bid[i] = 50.0 + i % 16 * 0.5;
        ask[i] = bid[i] + 0.5 + i % 3 * 0.5;
    }
    double* mid = new double[n];

    std::vector<double> times;
    for (int run = 1; run <= runs; ++run) {
        auto start = std::chrono::steady_clock::now();
        mids(bid.data(), ask.data(), mid, n);
        auto stop = std::chrono::steady_clock::now();
        times.push_back(std::chrono::duration<double, std::milli>(stop - start).count());
    }
    double best = *std::min_element(times.begin(), times.end());
    // std::cout << "first " << times[0] << " ms, best " << best << " ms\n";

    double checksum = 0;
    for (std::size_t i = 0; i < n; ++i) {
        checksum += mid[i];
    }
    std::cout << std::boolalpha << "runs timed: " << times.size() << '\n';
    std::cout << "best <= first: " << (best <= times[0]) << '\n';
    std::cout << std::fixed << std::setprecision(2) << "checksum " << checksum << '\n';
    delete[] mid;
    return 0;
}

