// -O2
#include <chrono>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

double total(const double* p, std::size_t n) {  // the work being timed
    double s = 0;
    for (std::size_t i = 0; i < n; ++i) {
        s += p[i];
    }
    return s;
}

double ms_since(std::chrono::steady_clock::time_point start) {
    return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
}

int main() {
    const std::size_t n = 1'000'000;
    std::vector<double> sizes(n);
    for (std::size_t i = 0; i < n; ++i) {
        sizes[i] = 1.0 + i % 5;
    }

    auto start = std::chrono::steady_clock::now();
    for (int run = 0; run < 100; ++run) {
        total(sizes.data(), n);  // 1. the result is thrown away
    }
    double ignored_ms = ms_since(start);

    start = std::chrono::steady_clock::now();
    const double test_quote[4] = {3, 1, 4, 1};
    double folded = 0;
    for (int run = 0; run < 100; ++run) {
        folded += total(test_quote, 4);  // 2. inputs the compiler can see
    }
    double folded_ms = ms_since(start);

    start = std::chrono::steady_clock::now();
    double real = 0;
    for (int run = 0; run < 100; ++run) {
        real += total(sizes.data(), n);  // 3. real data, and every result kept
    }
    double real_ms = ms_since(start);
    // std::cout << ignored_ms << ' ' << folded_ms << ' ' << real_ms << " ms\n";

    std::cout << std::fixed << std::setprecision(0);
    std::cout << "test quote: " << folded << '\n';
    std::cout << "real data: " << real << '\n';
    return 0;
}

