// -O2
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <vector>

int64_t sum_range(const std::vector<int64_t>& v) {
    int64_t s = 0;
    for (int64_t x : v) {
        s += x;
    }
    return s;
}

int64_t sum_index(const std::vector<int64_t>& v) {
    int64_t s = 0;
    for (std::size_t i = 0; i < v.size(); ++i) {
        s += v[i];
    }
    return s;
}

int64_t sum_pointer(const int64_t* p, std::size_t n) {
    int64_t s = 0;
    for (std::size_t i = 0; i < n; ++i) {
        s += p[i];
    }
    return s;
}

template <typename Work>
double best_ms(Work work) {  // the best of 5 runs, in milliseconds
    double best = 1e9;
    for (int run = 0; run < 5; ++run) {
        auto start = std::chrono::steady_clock::now();
        work();
        auto stop = std::chrono::steady_clock::now();
        best = std::min(best, std::chrono::duration<double, std::milli>(stop - start).count());
    }
    return best;
}

int main() {
    std::vector<int64_t> sizes(10'000'000);
    for (std::size_t i = 0; i < sizes.size(); ++i) {
        sizes[i] = i % 1000;
    }
    int64_t a = 0, b = 0, c = 0;
    double range_ms = best_ms([&] { a = sum_range(sizes); });
    double index_ms = best_ms([&] { b = sum_index(sizes); });
    double pointer_ms = best_ms([&] { c = sum_pointer(sizes.data(), sizes.size()); });
    // std::cout << range_ms << ' ' << index_ms << ' ' << pointer_ms << " ms\n";

    std::cout << "range for: " << a << '\n';
    std::cout << "index:     " << b << '\n';
    std::cout << "pointer:   " << c << '\n';
    return 0;
}

