// -O2
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <iostream>
#include <random>
#include <vector>

// Copies the sizes of block trades, 128 lots or more, into out, and returns how many.
std::size_t blocks_branchy(const int* size, std::size_t n, int* out) {
    std::size_t k = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (size[i] >= 128) {
            out[k] = size[i];
            ++k;
        }
    }
    return k;
}

std::size_t blocks_branchless(const int* size, std::size_t n, int* out) {
    std::size_t k = 0;
    for (std::size_t i = 0; i < n; ++i) {
        out[k] = size[i];     // always write the next slot
        k += size[i] >= 128;  // and keep it only by moving past it
    }
    return k;
}

template <typename Work>
double best_ms(Work work) {  // the best of 5 runs, in milliseconds
    double best = 1e9;
    for (int run = 0; run < 5; ++run) {
        auto start = std::chrono::steady_clock::now();
        work();
        auto stop = std::chrono::steady_clock::now();
        best = std::min(best, std::chrono::duration<double, std::milli>(stop - start).count());
    }
    return best;
}

int main() {
    std::mt19937 rng(42);  // a fixed seed gives the same numbers every run
    std::vector<int> shuffled(10'000'000);
    for (int& s : shuffled) {
        s = rng() % 256;
    }
    std::vector<int> sorted = shuffled;
    std::sort(sorted.begin(), sorted.end());
    std::vector<int> out(shuffled.size());

    std::size_t n = shuffled.size(), k1 = 0, k2 = 0, k3 = 0, k4 = 0;
    double t1 = best_ms([&] { k1 = blocks_branchy(shuffled.data(), n, out.data()); });
    double t2 = best_ms([&] { k2 = blocks_branchy(sorted.data(), n, out.data()); });
    double t3 = best_ms([&] { k3 = blocks_branchless(shuffled.data(), n, out.data()); });
    double t4 = best_ms([&] { k4 = blocks_branchless(sorted.data(), n, out.data()); });
    // std::cout << t1 << ' ' << t2 << ' ' << t3 << ' ' << t4 << " ms\n";

    std::cout << "branchy, shuffled:    " << k1 << '\n';
    std::cout << "branchy, sorted:      " << k2 << '\n';
    std::cout << "branchless, shuffled: " << k3 << '\n';
    std::cout << "branchless, sorted:   " << k4 << '\n';
    return 0;
}

